const OPS = ['<=', '>=', '<>', '^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.' && j + 1 < n && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', text: src.slice(i, j) })
      i = j
      continue
    }
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
      let j = i + 1
      while (j < n && ((src[j] >= 'A' && src[j] <= 'Z') || (src[j] >= 'a' && src[j] <= 'z'))) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'WORD', text: src.slice(i, j) })
      i = j
      continue
    }
    let matched = null
    for (const op of OPS) {
      if (src.startsWith(op, i)) { matched = op; break }
    }
    if (matched) {
      tokens.push({ type: 'OP', text: matched })
      i += matched.length
      continue
    }
    // Unrecognized character; emit a marker token that will never match the
    // grammar, forcing a parse failure.
    tokens.push({ type: 'UNKNOWN', text: c })
    i++
  }
  return tokens
}
"}

