{"file_path":"src/parser.js","content":"// Recursive-descent parser for formula bodies (the text after the leading '=').
// Produces a small AST. Throws ParseError on anything the grammar rejects.

import { tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const FUNC_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(op) {
    const t = this.peek()
    if (!t || t.type !== 'OP' || t.text !== op) throw new ParseError(`expected ${op}`)
    this.pos++
    return t
  }

  // Top-level entry.
  parseFormula() {
    const expr = this.parseCompare()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return expr
  }

  parseCompare() {
    let left = this.parseAdd()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && COMPARE_OPS.has(t.text)) {
        this.pos++
        const right = this.parseAdd()
        left = { type: 'binop', op: t.text, left, right }
      } else break
    }
    return left
  }

  parseAdd() {
    let left = this.parseMul()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.text === '+' || t.text === '-')) {
        this.pos++
        const right = this.parseMul()
        left = { type: 'binop', op: t.text, left, right }
      } else break
    }
    return left
  }

  parseMul() {
    let left = this.parsePow()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.text === '*' || t.text === '/')) {
        this.pos++
        const right = this.parsePow()
        left = { type: 'binop', op: t.text, left, right }
      } else break
    }
    return left
  }

  // Unary binds tighter than '^', and '^' groups right.
  parsePow() {
    const left = this.parseUnary()
    const t = this.peek()
    if (t && t.type === 'OP' && t.text === '^') {
      this.pos++
      const right = this.parsePow()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'OP' && (t.text === '-' || t.text === '+')) {
      this.pos++
      const operand = this.parseUnary()
      return { type: 'unary', op: t.text, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUMBER') {
      this.pos++
      return { type: 'number', value: parseFloat(t.text) }
    }
    if (t.type === 'OP' && t.text === '(') {
      this.pos++
      const expr = this.parseCompare()
      this.expectOp(')')
      return expr
    }
    if (t.type === 'WORD') {
      this.pos++
      const upper = t.text.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      const next = this.peek()
      if (next && next.type === 'OP' && next.text === '(') {
        this.pos++
        const args = this.parseArgList()
        this.expectOp(')')
        return { type: 'call', name: upper, args }
      }
      return { type: 'address', raw: t.text }
    }
    throw new ParseError('unexpected token')
  }

  // Parses a comma-separated argument list; each argument is either a range
  // (address ':' address) or a general expression. Ranges are only
  // recognized here, directly as function arguments.
  parseArgList() {
    const args = []
    const t = this.peek()
    if (t && t.type === 'OP' && t.text === ')') return args
    args.push(this.parseArgument())
    for (;;) {
      const c = this.peek()
      if (c && c.type === 'OP' && c.text === ',') {
        this.pos++
        args.push(this.parseArgument())
      } else break
    }
    return args
  }

  parseArgument() {
    const t = this.peek()
    const t2 = this.tokens[this.pos + 1]
    if (t && t.type === 'WORD' && t2 && t2.type === 'OP' && t2.text === ':') {
      const t3 = this.tokens[this.pos + 2]
      if (!t3 || t3.type !== 'WORD') throw new ParseError('expected address after :')
      this.pos += 3
      return { type: 'range', from: t.text, to: t3.text }
    }
    return this.parseCompare()
  }
}

export function parseFormula(src) {
  const tokens = tokenize(src)
  for (const tok of tokens) {
    if (tok.type === 'UNKNOWN') throw new ParseError('unrecognized character')
  }
  const parser = new Parser(tokens)
  return parser.parseFormula()
}

export const KNOWN_FUNCTIONS = FUNC_NAMES
"}

